import html
import json
from pathlib import Path

from .common import read_json, digest, write_json

NAMES = {"massive_en": "English request routing", "massive_nb": "Norwegian Bokmål request routing",
         "norec_no": "Norwegian review sentiment"}

def pct(value):
    return "n/a" if value is None else f"{value*100:.1f}%"

def interval(values):
    return "n/a" if not values or values[0] is None else f"{pct(values[0])}–{pct(values[1])}"

def delta_interval(values):
    return "n/a" if not values or values[0] is None else f"{values[0]*100:+.1f} to {values[1]*100:+.1f} percentage points"

def generate(path):
    path = Path(path)
    s = read_json(path)
    output = path.parent
    lines = ["# Local Laya benchmark — business findings", "", f"Run status: **{s['status']}**. Measured {s['created_utc']}.",
        "", "These are local measurements, not the model publisher's scores. Public test-set accuracy estimates performance on these tasks; it does not establish accuracy on your company's data.",
        "", "| Test | Model | Examples | Accuracy | 95% interval* | Macro F1 | Single request p50 |",
        "|---|---|---:|---:|---|---:|---:|"]
    for model, details in s["models"].items():
        for name, r in details["suites"].items():
            lines.append(f"| {NAMES[name]} | {model} | {r['n']} | {pct(r['accuracy'])} | {interval(r['accuracy_cluster95'])} | {r['macro_f1']:.3f} | {r['timing']['single_p50_ms']:.1f} ms |")
    lines += ["", "*Source-document cluster bootstrap, 2,000 resamples. NoReC sentences from one review are resampled together. Intervals cover sampling uncertainty, not training-data contamination or deployment drift.",
        "", "## Does this beat a simpler solution?", "",
        "The comparison below is a supervised word/character TF-IDF + linear SVM trained on official training data. Laya receives no task-specific training. This tests the practical alternative when labelled training data is available, not equal training conditions.",
        "", "| Test | Majority baseline | Simple trained classifier |", "|---|---:|---:|"]
    for name, r in s["baselines"].items():
        lines.append(f"| {NAMES[name]} | {pct(r['majority']['accuracy'])} | {pct(r['tfidf_linear_svm']['accuracy'])} |")
    lines += ["", "## Norwegian benefit from the multilingual checkpoint", "",
              "Both checkpoints receive the same texts and prompts. Positive differences favor Laya Multilingual.",
              "", "| Test | Difference in accuracy | Paired 95% interval |", "|---|---:|---|"]
    for name, r in s.get("comparisons", {}).items():
        lines.append(f"| {NAMES[name]} | {r['delta_accuracy_b_minus_a']*100:+.1f} percentage points | {delta_interval(r['delta_cluster95'])} |")
    lines += ["", "## Can it safely take work away from people?", "",
        "A policy is selected on a separate validation subset after calibration. It must have at least 30 accepted validation cases and a 95% Wilson lower accuracy bound of at least 95%. It is then evaluated once on the test set. This is evidence for a pilot, not a production guarantee.",
        "", "| Model / test | Selected threshold | Automated share of test | Accuracy on automated cases | 95% interval |",
        "|---|---:|---:|---:|---|"]
    for model, details in s["models"].items():
        for name, r in details["suites"].items():
            p = r["policy_test"]
            threshold = "None qualified" if p["threshold"] is None else f"{p['threshold']:.2f}"
            lines.append(f"| {model} / {NAMES[name]} | {threshold} | {pct(p['coverage'])} | {pct(p['accuracy'])} | {interval(p['accuracy_wilson95'])} |")
    lines += ["", "## What a software product can do with this", "",
        "Route incoming messages, tag feedback, or propose a queue to a support agent. Local inference can keep message content inside the organization's environment after the initial downloads. A user interface can show the proposed category, allow correction, and save that correction as future labelled training data.",
        "", "Start with suggestions that a person reviews. Enable automatic actions only on a separately validated in-domain workflow. A classifier's output should not itself trigger payments, account deletion, or other irreversible actions.",
        "", "Value comes from reduced handling time minus the cost of errors, hosting, monitoring, integration, and ongoing maintenance. The HTML report contains an editable NOK calculator. Its amounts are scenarios, not measured savings; local software still has infrastructure and staffing costs.",
        "", "## Limits that affect the decision", "",
        "- MASSIVE tests 18 assistant-service categories, not support tickets or all 60 intents. English and Bokmål test IDs are matched. This is a routing proxy.",
        "- NoReC tests three-way sentiment on published reviews. It contains Norwegian varieties but this version has no row-level variety tag, so no separate Bokmål/Nynorsk public score is claimed.",
        "- Separate authored diagnostics cover Bokmål, Nynorsk, negation, quotes, typos, code switching, binary decisions, ordinal urgency, option order, and long inputs. They need native-speaker review and are not pooled into headline accuracy.",
        "- Public benchmarks may have appeared during pretraining or fine-tuning. No contamination-free claim is possible without private, newly labelled data.",
        "- Calibration uses the SDK's four-decimal probabilities, renormalized. NLL clips zero probabilities at 1e-8. ECE uses ten equal-width bins; low ECE alone does not mean good accuracy.",
        "- Prompts are frozen, English by default, with no test-set tuning. Native checkpoint token budgets are retained and all truncation is counted. SDK-shipped/clamped temperatures remain in the raw results.",
        "- Request latency is warm, batch-one inference on this machine. Batch throughput, model load time, downloads, and network/service overhead are separate.",
        "", "## Evidence", "",
        "See `summary.json` for per-class precision/recall/F1, confusion matrices, calibration, thresholds, sampling checks, and paired comparisons. `predictions.jsonl` records every measured decision; `errors.csv` lists mistakes. Both raw exports contain source text and should stay local, especially NoReC's CC-BY-NC material.",
        "", "Sources: [Laya](https://huggingface.co/convaiinnovations/laya), [Laya Multilingual](https://huggingface.co/convaiinnovations/laya-multilingual), [MASSIVE](https://huggingface.co/datasets/AmazonScience/massive), [NoReC sentence](https://huggingface.co/datasets/ltg/norec_sentence). Exact revisions and file hashes are saved with the results."]
    (output/"business_report.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
    payload = json.dumps(s, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("&", "\\u0026")
    (output/"report.html").write_text(HTML.replace("__DATA__",payload),encoding="utf-8")
    write_json(output/"report-build.json", {"summary_sha256":digest(path), "report_source_sha256":digest(__file__),
               "html_sha256":digest(output/"report.html"), "markdown_sha256":digest(output/"business_report.md")})

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Laya · Local evidence & business value</title>
<style>
:root{--ink:#173431;--muted:#617572;--paper:#f6f8f4;--line:#d6e0d8;--green:#167969;--blue:#4b72af;--amber:#b27121;--red:#a3463f}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 system-ui,Segoe UI,sans-serif}header{background:#143d35;color:#fff;padding:38px max(5vw,20px) 42px}header p{color:#c7ddd4;max-width:770px}.eyebrow{letter-spacing:.17em;font-size:11px;font-weight:700;text-transform:uppercase}h1{font-size:clamp(30px,4vw,48px);line-height:1.16;font-weight:600;letter-spacing:-.04em;margin:12px 0 18px}h2{font-size:25px;letter-spacing:-.03em;margin:0 0 8px}h3{font-size:17px;margin:0 0 10px}p{margin:0 0 16px}.wrap{max-width:1250px;margin:auto;padding:26px 26px 70px}.status{display:inline-block;border:1px solid #84ad9e;border-radius:20px;padding:3px 12px;font-size:12px}nav{display:flex;gap:10px;flex-wrap:wrap;border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:28px}button{font:inherit;background:transparent;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:8px 18px;cursor:pointer}button.active{background:var(--ink);color:white}section[hidden]{display:none}.card{background:#fff;border:1px solid var(--line);border-radius:13px;padding:23px;margin-bottom:20px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.two{display:grid;grid-template-columns:1.1fr 1fr;gap:20px}.stat{font-size:34px;font-weight:650;letter-spacing:-.04em}.muted,small{color:var(--muted)}small{font-size:12px}.callout{border-left:4px solid var(--green);padding:16px 20px;background:#eaf2eb;border-radius:4px;margin:20px 0}.warn{border-color:var(--amber);background:#fff4e1}.danger{color:var(--red)}table{border-collapse:collapse;width:100%;font-size:14px}th{text-align:left;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.045em;border-bottom:1px solid var(--line);padding:12px 10px}td{padding:11px 10px;border-bottom:1px solid #e8ede7;vertical-align:top}td.num{text-align:right;font-variant-numeric:tabular-nums}.table-scroll{overflow-x:auto}select,input{font:inherit;border:1px solid #b8cbbf;border-radius:7px;background:#fff;padding:8px 10px;color:var(--ink);max-width:100%}select{min-width:220px}label{display:block;color:var(--muted);font-size:12px;margin:10px 0 4px}input{width:100%}.fields{display:grid;grid-template-columns:1fr 1fr;gap:8px 20px}.barrow{margin:18px 0}.barline{display:flex;justify-content:space-between;gap:10px;font-size:13px}.track{height:13px;background:#e9eee7;border-radius:5px;overflow:hidden;margin-top:6px}.fill{height:100%;background:var(--green)}.blue{background:var(--blue)}.gray{background:#a1b0a8}a{color:var(--green)}details{margin:15px 0}summary{cursor:pointer;font-weight:600}code{font-size:12px}footer{font-size:12px;border-top:1px solid var(--line);padding-top:20px;color:var(--muted)}.pill{display:inline-block;padding:2px 9px;border-radius:20px;background:#eaf2eb;font-size:12px}.legend{display:flex;gap:18px;font-size:12px;color:var(--muted)}.dot{width:9px;height:9px;display:inline-block;border-radius:50%;margin-right:5px}.confusion td{font-size:12px;text-align:center}.confusion th{font-size:10px}.chart{min-height:140px}.intro{max-width:900px}.space{margin-top:26px}@media(max-width:820px){.grid,.two{grid-template-columns:1fr}.wrap{padding:20px 14px}.fields{grid-template-columns:1fr}td,th{padding:9px 7px}}
</style></head><body>
<header><div class="eyebrow">Local benchmark / Decision support</div><h1>Can Laya earn its place<br>in your software?</h1><p>Measured accuracy, Norwegian language coverage, and the economics of putting classification to work. Every headline number comes from this local run.</p><span class="status" id="run-status"></span></header>
<main class="wrap"><nav aria-label="Report sections"><button class="active" data-tab="results">Measured results</button><button data-tab="value">Business value</button><button data-tab="quality">Reliability & Norwegian</button><button data-tab="method">Method & evidence</button></nav>
<section id="results"><div class="intro"><h2>Accuracy before automation</h2><p class="muted">Choose a task to compare both checkpoints with a simple trained classifier. Different tasks stay separate; there is no misleading overall accuracy score.</p></div><label for="suite">Evaluation task</label><select id="suite"></select><div id="headline" class="grid space"></div><div class="two"><div class="card"><h3>Correct decisions on held-out examples</h3><div id="bars" class="chart"></div><small>Human-labelled public test data; the trained baseline has access to the official training split. Laya is zero-shot.</small></div><div class="card"><h3>What the comparison says</h3><div id="verdict"></div><div class="callout">Use these scores to choose a pilot. Measure on your own messages before deciding how much work to automate.</div></div></div><div class="card table-scroll"><h3>Quality and local performance</h3><table><thead><tr><th>Checkpoint</th><th>Accuracy / 95% interval</th><th>Macro F1</th><th>Warm p50 / p95</th><th>Batch throughput</th></tr></thead><tbody id="measurements"></tbody></table><p class="muted space"><small>Latency is measured separately with one request at a time. Throughput uses batches. Downloads, cold load, application and network overhead are excluded.</small></p></div></section>
<section id="value" hidden><h2>Turn quality into a business decision</h2><p class="muted intro">Potential applications include suggesting a support queue, tagging feedback, and prioritizing review. Local inference gives you control over where message content is processed.</p><div class="two"><div class="card"><h3>Editable cost scenario · NOK / month</h3><label for="roi-suite">Task used as a proxy</label><select id="roi-suite"></select><label for="roi-model">Model</label><select id="roi-model"></select><label for="strategy">Automation strategy</label><select id="strategy"><option value="gated">Validation-selected confidence policy</option><option value="all">Automate every decision (risk scenario)</option></select><div class="fields"><div><label for="volume">Monthly messages</label><input id="volume" type="number" min="0" value="10000"></div><div><label for="seconds">Seconds saved per automated message</label><input id="seconds" type="number" min="0" value="60"></div><div><label for="hourly">Staff cost, NOK per hour</label><input id="hourly" type="number" min="0" value="600"></div><div><label for="error-cost">Extra cost per wrong decision, NOK</label><input id="error-cost" type="number" min="0" value="250"></div><div><label for="hosting">Monthly hosting & operations, NOK</label><input id="hosting" type="number" min="0" value="2000"></div><div><label for="integration">Monthly integration amortization, NOK</label><input id="integration" type="number" min="0" value="1000"></div></div></div><div class="card"><h3>Illustrative net monthly benefit</h3><div class="stat" id="net"></div><div id="roi-detail"></div><div class="callout warn">Scenario, not a savings forecast. Public benchmark error rates are not your production error rates. The default money and time inputs are assumptions; replace them with your own measurements.</div><small>Formula: automated volume × seconds saved ÷ 3,600 × hourly staff cost − wrong automated decisions × error cost − hosting − amortized integration.</small></div></div><div class="card"><h3>A practical first release</h3><ol><li>Suggest a category inside the existing workflow and let staff correct it.</li><li>Measure handling time, overrides and downstream mistakes on a private holdout.</li><li>Validate separate quality targets for Bokmål, Nynorsk and high-cost categories.</li><li>Automate only the cases that meet those targets; keep the rest in human review.</li></ol><p class="muted">Budget for monitoring, maintenance and fallback handling. Keep irreversible actions behind application permissions and appropriate review.</p></div></section>
<section id="quality" hidden><h2>Confidence has to be earned</h2><p class="muted">A confident answer can still be wrong. Calibration and threshold selection use different validation groups; the final policy is measured on untouched test examples.</p><label for="quality-suite">Task</label><select id="quality-suite"></select><div class="card table-scroll space"><table><thead><tr><th>Model</th><th>Raw ECE → fitted ECE</th><th>Errors at ≥90% raw confidence</th><th>Selected coverage</th><th>Selected accuracy / 95% interval</th></tr></thead><tbody id="confidence"></tbody></table><p class="muted space"><small>ECE measures the gap between confidence and correctness (lower is better). The policy needs ≥30 validation decisions and a 95% lower accuracy bound ≥95%. A policy qualifying on validation may still fail on test.</small></p></div><div class="two"><div class="card"><h3>Norwegian is more than one test</h3><p><strong>Bokmål:</strong> matched English–Norwegian request routing provides a direct language comparison.</p><p><strong>Norwegian reviews:</strong> human-labelled negative, neutral and positive sentences. Variety is not tagged per row in this dataset.</p><p><strong>Nynorsk:</strong> authored support and negation diagnostics only. This is insufficient to certify Nynorsk production accuracy.</p><div class="callout warn">Authored diagnostics require native-speaker review. They are never added to the headline accuracy.</div></div><div class="card"><h3>Sensitivity to option order</h3><div id="order"></div><small>The first 100 examples in deterministic label-blind order are rerun with reversed choices. This reveals fragility without replacing the original score.</small></div></div><details class="card"><summary>Authored diagnostic results: support, negation, scoring and long inputs</summary><div class="table-scroll"><table><thead><tr><th>Model</th><th>Diagnostic</th><th>Cases</th><th>Accuracy</th><th>Macro F1</th><th>Truncated</th></tr></thead><tbody id="diagnostics"></tbody></table></div></details><details class="card"><summary>Per-category precision, recall, F1 and confusion matrices</summary><div id="classes"></div></details></section>
<section id="method" hidden><h2>Evidence you can inspect and reproduce</h2><div class="card"><h3>Evaluation protocol</h3><ul><li>Pinned model and dataset revisions; local Python virtual environment; no hosted inference or LLM judge.</li><li>Official train/validation/test splits. Exact normalized text duplicates removed with test priority. NoReC review groups checked for split leakage.</li><li>MASSIVE English and Bokmål use the same example IDs and all 18 service categories. This is not a benchmark of all 60 intents.</li><li>Temperature fitted on one half of validation source groups; policy selected on the other half. Test outcomes do not tune prompts, temperatures or thresholds.</li><li>95% accuracy intervals use 2,000 source-group bootstrap resamples. Multiple NoReC sentences from one review remain grouped.</li><li>All public test errors remain in the results. Failed runs are explicitly marked incomplete.</li></ul><div class="callout warn">Public test data may overlap the models' training history. Newly labelled private examples are required for a contamination-resistant production decision.</div></div><div class="two"><div class="card"><h3>Local environment</h3><div id="environment"></div></div><div class="card"><h3>Evidence files</h3><p><a href="business_report.md">Business findings (Markdown)</a><br><a href="summary.json">Full metrics & run manifest (JSON)</a><br><a href="predictions.jsonl">Every prediction (JSONL)</a><br><a href="errors.csv">Error review (CSV)</a></p><small>The two raw exports contain dataset text. NoReC is CC-BY-NC-4.0; keep evaluation data local and review its terms before redistributing. The two model cards list Apache-2.0 and MASSIVE lists CC-BY-4.0.</small></div></div><div class="card"><h3>Measured truncation</h3><div id="truncation"></div><p class="muted">The SDK's native token limits are used in the primary evaluation. Long-document diagnostics additionally test a 2,048-token multilingual setting. The SDK rounds probabilities to four decimals; calibration renormalizes them and clips log-loss zeros at 1e-8.</p></div><div class="card"><h3>Sources</h3><p><a href="https://huggingface.co/convaiinnovations/laya">Laya model card</a> · <a href="https://huggingface.co/convaiinnovations/laya-multilingual">Multilingual model card</a> · <a href="https://huggingface.co/datasets/AmazonScience/massive">MASSIVE</a> · <a href="https://huggingface.co/datasets/ltg/norec_sentence">NoReC sentence</a></p></div></section>
<footer>Local evidence, explicit assumptions. This report does not contact external services. Accuracy is task-specific; business savings require a measured workflow pilot.</footer></main>
<script type="application/json" id="data">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent);
const names={massive_en:'English request routing',massive_nb:'Norwegian Bokmål request routing',norec_no:'Norwegian review sentiment'};
const models=Object.keys(D.models),suites=Object.keys(D.baselines);
const $=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pc=x=>x==null?'n/a':(100*x).toFixed(1)+'%',ci=x=>!x||x[0]==null?'n/a':pc(x[0])+'–'+pc(x[1]),dci=x=>!x||x[0]==null?'n/a':(100*x[0]).toFixed(1)+' to '+(100*x[1]).toFixed(1)+' percentage points',number=x=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:0}).format(x);
$('run-status').textContent=D.status.toUpperCase()+' · '+D.created_utc.slice(0,10)+' · '+(D.environment.gpu||'CPU');
for(const id of ['suite','roi-suite','quality-suite']){$(id).innerHTML=suites.map(k=>`<option value="${esc(k)}">${esc(names[k])}</option>`).join('');$(id).value='massive_nb';}
$('roi-model').innerHTML=models.map(m=>`<option>${esc(m)}</option>`).join('');$('roi-model').value=models.includes('laya-multilingual')?'laya-multilingual':models[0];
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==b.dataset.tab);});
function results(){const k=$('suite').value,base=D.baselines[k],rs=models.filter(m=>D.models[m].suites[k]).map(m=>[m,D.models[m].suites[k]]);if(!rs.length)return;const best=rs.reduce((a,b)=>a[1].accuracy>b[1].accuracy?a:b);
$('headline').innerHTML=`<div class="card"><div class="eyebrow">Best Laya accuracy</div><div class="stat">${pc(best[1].accuracy)}</div><small>${esc(best[0])} · ${number(best[1].n)} test examples</small></div><div class="card"><div class="eyebrow">Simple trained classifier</div><div class="stat">${pc(base.tfidf_linear_svm.accuracy)}</div><small>TF-IDF + linear SVM · trained on official training data</small></div><div class="card"><div class="eyebrow">Human review still matters</div><div class="stat">${number((1-best[1].accuracy)*1000)}</div><small>Wrong decisions per 1,000 if every result is accepted</small></div>`;
const bars=[...rs.map(([m,r],i)=>[m,r.accuracy,i?'blue':'']),['Simple trained classifier',base.tfidf_linear_svm.accuracy,'gray'],['Majority baseline',base.majority.accuracy,'gray']];
$('bars').innerHTML=bars.map(([name,value,color])=>`<div class="barrow"><div class="barline"><span>${esc(name)}</span><strong>${pc(value)}</strong></div><div class="track"><div class="fill ${color}" style="width:${value*100}%"></div></div></div>`).join('');
const diff=best[1].accuracy-base.tfidf_linear_svm.accuracy,comp=D.comparisons[k];
$('verdict').innerHTML=`<p>The best Laya checkpoint scores <strong>${Math.abs(diff*100).toFixed(1)} percentage points ${diff>=0?'above':'below'}</strong> the simple trained classifier on this test.</p>`+(comp?`<p>Multilingual minus English checkpoint: <strong>${(comp.delta_accuracy_b_minus_a*100).toFixed(1)} points</strong>, paired 95% interval ${dci(comp.delta_cluster95)}.</p>`:'')+`<p class="muted">${k==='norec_no'?'This measures sentiment in review sentences.':'This measures assistant-service routing, a proxy for a business routing workflow.'}</p>`;
$('measurements').innerHTML=rs.map(([m,r])=>`<tr><td>${esc(m)}</td><td><strong>${pc(r.accuracy)}</strong><br><small>${ci(r.accuracy_cluster95)}</small></td><td>${r.macro_f1.toFixed(3)}</td><td>${r.timing.single_p50_ms.toFixed(1)} / ${r.timing.single_p95_ms.toFixed(1)} ms</td><td>${r.timing.samples_per_second.toFixed(1)} / sec</td></tr>`).join('');}
function roi(){const r=D.models[$('roi-model').value]?.suites[$('roi-suite').value];if(!r)return;const gated=$('strategy').value==='gated',p=r.policy_test,c=gated?p.coverage:1,a=gated?(p.accuracy??0):r.accuracy;
const read=id=>Math.max(0,Number($(id).value)||0),v=read('volume'),accepted=v*c,wrong=accepted*(1-a),hours=accepted*read('seconds')/3600,gross=hours*read('hourly'),loss=wrong*read('error-cost'),fixed=read('hosting')+read('integration'),net=gross-loss-fixed;
$('net').textContent=(net<0?'−':'')+'NOK '+number(Math.abs(net));$('net').classList.toggle('danger',net<0);
$('roi-detail').innerHTML=`<p class="muted">${gated?'Validation-selected policy':'Accept every prediction'} · measured test coverage ${pc(c)}</p><table><tr><td>Automated / human-reviewed messages</td><td class="num">${number(accepted)} / ${number(v-accepted)}</td></tr><tr><td>Estimated wrong automated decisions</td><td class="num">${number(wrong)}</td></tr><tr><td>Handling time saved</td><td class="num">${hours.toFixed(1)} hours</td></tr><tr><td>Value of saved time</td><td class="num">NOK ${number(gross)}</td></tr><tr><td>Expected extra error cost</td><td class="num">NOK ${number(loss)}</td></tr><tr><td>Hosting + integration amortization</td><td class="num">NOK ${number(fixed)}</td></tr></table>`+(gated&&p.threshold==null?'<p class="danger space">No confidence threshold met the validation quality target. This policy automates zero cases.</p>':'')+(gated&&p.accuracy_wilson95[0]!=null&&p.accuracy_wilson95[0]<.95?'<p class="danger space">The selected policy did not demonstrate a 95% lower accuracy bound of 95% on test. Do not treat it as qualified for deployment.</p>':'');}
function quality(){const k=$('quality-suite').value,rs=models.filter(m=>D.models[m].suites[k]).map(m=>[m,D.models[m].suites[k]]);
$('confidence').innerHTML=rs.map(([m,r])=>`<tr><td>${esc(m)}</td><td>${r.raw_calibration.ece.toFixed(3)} → ${r.fitted_calibration.ece.toFixed(3)}</td><td>${r.raw_calibration.confident_errors} of ${r.raw_calibration.confident_count}</td><td>${pc(r.policy_test.coverage)}</td><td>${pc(r.policy_test.accuracy)}<br><small>${ci(r.policy_test.accuracy_wilson95)}</small></td></tr>`).join('');
$('order').innerHTML=rs.map(([m,r])=>`<p><strong>${esc(m)}</strong><br>${r.option_order_audit.changed_predictions} / ${r.option_order_audit.n} predictions changed.<br><small>Accuracy: ${pc(r.option_order_audit.original_accuracy)} → ${pc(r.option_order_audit.reversed_accuracy)}</small></p>`).join('');
$('classes').innerHTML=rs.map(([m,r])=>`<h3 class="space">${esc(m)}</h3><div class="table-scroll"><table><thead><tr><th>Class</th><th>Precision</th><th>Recall</th><th>F1</th><th>Support</th></tr></thead><tbody>${r.labels.map(l=>{const v=r.per_class[l];return `<tr><td>${esc(l)}</td><td>${v.precision.toFixed(3)}</td><td>${v.recall.toFixed(3)}</td><td>${v['f1-score'].toFixed(3)}</td><td>${v.support}</td></tr>`}).join('')}</tbody></table><p class="muted space">Confusion matrix: rows are actual classes; columns are predictions.</p><table class="confusion"><thead><tr><th>Actual ↓ / predicted →</th>${r.labels.map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${r.confusion_matrix.map((row,i)=>`<tr><th>${esc(r.labels[i])}</th>${row.map((v,j)=>`<td style="background:rgba(22,121,105,${.03+.5*v/Math.max(1,...row)})">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`).join('');}
$('diagnostics').innerHTML=models.flatMap(m=>Object.entries(D.models[m].diagnostics||{}).map(([k,r])=>`<tr><td>${esc(m)}</td><td>${esc(k)}</td><td>${r.n}</td><td>${pc(r.accuracy)}</td><td>${r.macro_f1.toFixed(3)}</td><td>${r.truncated_inputs}</td></tr>`)).join('');
$('environment').innerHTML=`<p><strong>${esc(D.environment.gpu||'CPU')}</strong><br>${esc(D.environment.platform)}<br>Python ${esc(D.environment.python)} · Torch ${esc(D.environment.torch)}<br>${D.environment.ram_gb.toFixed(1)} GB system RAM</p><p class="muted">Batch size ${D.arguments.batch_size}; ${D.environment.threads} CPU threads. Inference uses the SDK's eager path; numerical settings and source hashes are in the manifest.</p>`;
$('truncation').innerHTML=models.flatMap(m=>Object.entries(D.models[m].suites).map(([k,r])=>`<p><strong>${esc(m)} / ${esc(names[k])}</strong>: ${r.audit.truncated_inputs} of ${r.n} inputs truncated; ${r.audit.options_truncated} option descriptions shortened; instruction shortened: ${r.audit.instruction_truncated?'yes':'no'}.</p>`)).join('');
$('suite').onchange=results;$('quality-suite').onchange=quality;['roi-suite','roi-model','strategy','volume','seconds','hourly','error-cost','hosting','integration'].forEach(id=>$(id).addEventListener('input',roi));results();roi();quality();
</script></body></html>'''
